#!/usr/bin/env python3
"""Emit a JSON port map for a Verilog file generated by voodoo.diff.GenOne.

The Amaranth port (docs/amaranth-rewrite-plan.md §4.2) has to drive the Spinal module through
its flattened Verilog port list: `io_<bundle>_<stream>_valid/ready/payload_<field>_<sub>`, `_N`
Vec indices, and so on. This tool turns that flat list into structured data so the diff harness
can build the mapping table mechanically instead of by hand.

Usage:
    python3 fpga/src/voodoo/diff/ports.py fpga/rtl/diff/PciFifo_spinal.v
    python3 fpga/src/voodoo/diff/ports.py fpga/rtl/diff/*.v -o fpga/src/voodoo/diff/portmaps

Standard library only; no third-party dependencies.

Output schema (per file):
{
  "module":        "<Top>_spinal",
  "source":        "<basename>.v",
  "generator":     "SpinalHDL v1.15.0 ...",          # from the header comment
  "clock_domain":  {"clock": "clk", "reset": "reset",
                    "reset_kind": "sync|async|none",
                    "reset_active_level": "high|low|unknown"},
  "counts":        {"ports": n, "input_bits": n, "output_bits": n},
  "ports":         [ <port>, ... ],
  "streams":       { "<base>": {"kind": "stream|flow",
                                "valid": "...", "ready": "...",
                                "payload": ["..."]} },
  "scalars":       [ "<name>", ... ]
}

<port>:
{
  "name":        "io_cpuSide_cmd_payload_fragment_address",
  "direction":   "input" | "output" | "inout",
  "verilog_type":"wire" | "reg",
  "width":       12,
  "msb": 11, "lsb": 0,                # null for 1-bit ports
  "signed":      false,               # Spinal always emits unsigned vectors
  "io_bundle":   true,                # name started with the `io_` prefix
  "path":        ["cpuSide","cmd","payload","fragment","address"],
  "role":        "payload",           # valid | ready | payload | none | clock | reset
  "stream":      "io_cpuSide_cmd",    # handshake group this port belongs to, if any
  "bundle_path": ["cpuSide","cmd"],   # path up to the handshake
  "field_path":  ["fragment","address"],   # path below `payload`
  "indices":     [{"position": 3, "index": 0}],  # numeric segments (Vec elements)
  "trailing_index": null,             # numeric last segment: Vec index OR Spinal's `_N`
                                      # duplicate-name disambiguator — ambiguous, see below
  "leaf":        "address"
}
"""

from __future__ import annotations

import argparse
import json
import os
import re
import sys

# ---------------------------------------------------------------------------------------------
# Verilog header parsing
# ---------------------------------------------------------------------------------------------

_COMPONENT_RE = re.compile(r"^//\s*Component\s*:\s*(\S+)", re.M)
_GENERATOR_RE = re.compile(r"^//\s*Generator\s*:\s*(.+?)\s*$", re.M)
_MODULE_RE = re.compile(r"^module\s+([A-Za-z_$][\w$]*)\s*\(", re.M)

_PORT_RE = re.compile(
    r"^\s*(input|output|inout)\s+"
    r"(wire|reg|logic)?\s*"
    r"(signed\s+)?"
    r"(?:\[\s*(\d+)\s*:\s*(\d+)\s*\]\s*)?"
    r"([A-Za-z_$][\w$]*)\s*,?\s*$"
)


def find_top_module(text: str, path: str, explicit: str | None) -> str:
    """Pick the top module: --top, then the `// Component :` header, then `*_spinal`."""
    if explicit:
        return explicit
    m = _COMPONENT_RE.search(text)
    if m:
        return m.group(1)
    names = _MODULE_RE.findall(text)
    for n in names:
        if n.endswith("_spinal"):
            return n
    if names:
        return names[0]
    raise SystemExit(f"{path}: no module found")


def module_header(text: str, module: str) -> str:
    """Return the text between `module <name> (` and the closing `);`."""
    start = re.search(r"^module\s+" + re.escape(module) + r"\s*\(", text, re.M)
    if not start:
        raise SystemExit(f"module {module} not found")
    end = text.index(");", start.end())
    return text[start.end():end]


def parse_ports(header: str) -> list[dict]:
    ports = []
    for line in header.splitlines():
        line = line.split("//")[0].rstrip()
        if not line.strip():
            continue
        m = _PORT_RE.match(line)
        if not m:
            continue
        direction, vtype, signed, msb, lsb, name = m.groups()
        if msb is None:
            width, msb_i, lsb_i = 1, None, None
        else:
            msb_i, lsb_i = int(msb), int(lsb)
            width = abs(msb_i - lsb_i) + 1
        ports.append(
            {
                "name": name,
                "direction": direction,
                "verilog_type": vtype or "wire",
                "width": width,
                "msb": msb_i,
                "lsb": lsb_i,
                "signed": bool(signed),
            }
        )
    return ports


# ---------------------------------------------------------------------------------------------
# Spinal name decomposition
# ---------------------------------------------------------------------------------------------

CLOCK_NAMES = {"clk", "clock", "coreClk"}
RESET_NAMES = {"reset", "resetn", "rst", "rst_n"}
HANDSHAKE = ("valid", "ready", "payload")


def decompose(name: str) -> dict:
    """Split a Spinal-generated port name into its structural pieces.

    Rules observed in this project's generated Verilog (see
    docs/amaranth/spinal-naming-and-harness.md):

      * ports declared inside a Component's `io` Bundle are prefixed `io_`; ports declared at
        component level (Rasterizer's `i`/`o`, AfixOps' operands) are not.
      * Stream  -> `<base>_valid`, `<base>_ready`, `<base>_payload[_<field>…]`
        Flow     -> `<base>_valid`, `<base>_payload[_<field>…]`   (no ready)
        Fragment -> an extra `_fragment` level under `payload`, with `_last` beside it
      * nested Bundles add one `_<field>` level each
      * Vec elements add a numeric segment `_<i>`; a numeric segment may appear anywhere
        (`coeffs_0_a`) or at the end (`xrange_0`)
      * Spinal also appends `_<N>` to disambiguate colliding names. A trailing numeric segment
        is therefore ambiguous on its own: `trailing_index` records it, and the caller resolves
        it by checking whether siblings `_0.._k` exist (`streams`/`vec_groups` below do that).
    """
    io_bundle = name.startswith("io_")
    body = name[3:] if io_bundle else name
    segs = body.split("_")

    out: dict = {
        "io_bundle": io_bundle,
        "path": segs,
        "role": "none",
        "stream": None,
        "bundle_path": [],
        "field_path": [],
        "indices": [{"position": i, "index": int(s)} for i, s in enumerate(segs) if s.isdigit()],
        "trailing_index": int(segs[-1]) if segs and segs[-1].isdigit() else None,
        "leaf": segs[-1] if segs else body,
    }

    if name in CLOCK_NAMES:
        out["role"] = "clock"
        return out
    if name in RESET_NAMES:
        out["role"] = "reset"
        return out

    prefix = "io_" if io_bundle else ""
    # Locate the handshake keyword closest to the end that still has a base in front of it.
    for i in range(len(segs) - 1, -1, -1):
        if segs[i] in HANDSHAKE and i > 0:
            out["role"] = segs[i]
            out["stream"] = prefix + "_".join(segs[:i])
            out["bundle_path"] = segs[:i]
            out["field_path"] = segs[i + 1:]
            break
    return out


def group_streams(ports: list[dict]) -> dict:
    groups: dict[str, dict] = {}
    for p in ports:
        base = p.get("stream")
        if not base:
            continue
        g = groups.setdefault(base, {"kind": "flow", "valid": None, "ready": None, "payload": []})
        if p["role"] == "valid":
            g["valid"] = p["name"]
        elif p["role"] == "ready":
            g["ready"] = p["name"]
            g["kind"] = "stream"
        else:
            g["payload"].append(p["name"])
    for g in groups.values():
        if g["valid"] is None and g["ready"] is None:
            g["kind"] = "bundle"
    return groups


def mark_vec_groups(ports: list[dict]) -> None:
    """Resolve the trailing `_N` ambiguity.

    A trailing numeric segment is a Vec index when a sibling with index 0 (and, for indices > 0,
    index-1) exists under the same prefix. Otherwise it is Spinal's duplicate-name suffix.
    """
    by_prefix: dict[str, set] = {}
    for p in ports:
        if p.get("trailing_index") is None:
            continue
        prefix = p["name"].rsplit("_", 1)[0]
        by_prefix.setdefault(prefix, set()).add(p["trailing_index"])
    for p in ports:
        ti = p.get("trailing_index")
        if ti is None:
            p["trailing_index_kind"] = None
            continue
        prefix = p["name"].rsplit("_", 1)[0]
        seen = by_prefix.get(prefix, set())
        contiguous = 0 in seen and all(i in seen for i in range(0, max(seen) + 1))
        p["trailing_index_kind"] = "vec_index" if contiguous and len(seen) > 1 else "ambiguous"


# ---------------------------------------------------------------------------------------------
# Clock domain
# ---------------------------------------------------------------------------------------------

def clock_domain(text: str, ports: list[dict]) -> dict:
    clocks = [p["name"] for p in ports if p.get("role") == "clock"]
    resets = [p["name"] for p in ports if p.get("role") == "reset"]
    info = {
        "clock": clocks[0] if clocks else None,
        "reset": resets[0] if resets else None,
        "reset_kind": "none",
        "reset_active_level": "unknown",
    }
    if not resets:
        return info
    rst = resets[0]
    if re.search(r"always\s*@\s*\(\s*posedge\s+\w+\s+or\s+posedge\s+" + re.escape(rst), text):
        info["reset_kind"], info["reset_active_level"] = "async", "high"
    elif re.search(r"always\s*@\s*\(\s*posedge\s+\w+\s+or\s+negedge\s+" + re.escape(rst), text):
        info["reset_kind"], info["reset_active_level"] = "async", "low"
    elif re.search(r"if\s*\(\s*" + re.escape(rst) + r"\s*\)", text):
        info["reset_kind"], info["reset_active_level"] = "sync", "high"
    elif re.search(r"if\s*\(\s*!\s*" + re.escape(rst) + r"\s*\)", text):
        info["reset_kind"], info["reset_active_level"] = "sync", "low"
    return info


# ---------------------------------------------------------------------------------------------

def port_map(path: str, top: str | None = None) -> dict:
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        text = fh.read()

    module = find_top_module(text, path, top)
    ports = parse_ports(module_header(text, module))
    for p in ports:
        p.update(decompose(p["name"]))
    mark_vec_groups(ports)

    gen = _GENERATOR_RE.search(text)
    return {
        "module": module,
        "source": os.path.basename(path),
        "generator": gen.group(1) if gen else None,
        "clock_domain": clock_domain(text, ports),
        "counts": {
            "ports": len(ports),
            "input_bits": sum(p["width"] for p in ports if p["direction"] == "input"),
            "output_bits": sum(p["width"] for p in ports if p["direction"] == "output"),
        },
        "ports": ports,
        "streams": group_streams(ports),
        "scalars": [p["name"] for p in ports if p["role"] == "none"],
    }


def main(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("files", nargs="+", help="generated *_spinal.v files")
    ap.add_argument("-o", "--out-dir", help="write <Module>.json here instead of stdout")
    ap.add_argument("--top", help="top module name (default: `// Component :` header)")
    ap.add_argument("--strip-suffix", default="_spinal",
                    help="suffix removed from the module name for the JSON filename")
    args = ap.parse_args(argv)

    if args.out_dir:
        os.makedirs(args.out_dir, exist_ok=True)

    for path in args.files:
        pm = port_map(path, args.top)
        blob = json.dumps(pm, indent=2) + "\n"
        if args.out_dir:
            stem = pm["module"]
            if args.strip_suffix and stem.endswith(args.strip_suffix):
                stem = stem[: -len(args.strip_suffix)]
            dest = os.path.join(args.out_dir, stem + ".json")
            with open(dest, "w", encoding="utf-8") as fh:
                fh.write(blob)
            print(f"{dest}: {pm['counts']['ports']} ports, "
                  f"{len(pm['streams'])} handshake groups")
        else:
            sys.stdout.write(blob)
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
